import { Object3D } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {{position?: number[], rotation?: number[], scale?: number[]}} [transform]
 * @property {{meshUrl?: string}} [assets]
 * @property {Array<{name:string,params:any}>} [cinematicPrimitives]
 * @property {Array<any>} [dataBindings]
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>any} glbLoader
 * @property {{[key:string]:(target:Object3D,params:any)=>void}} primitives
 * @property {(event:string)=>void} [emit]
 */

/**
 * Create a stat‑tile node for the Collection hub.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
    // -----------------------------------------------------------------
    // Base object
    // -----------------------------------------------------------------
    const root = new Object3D();

    // Apply transform (fallback to defaults if not provided)
    const position = config.transform?.position ?? [0, 0, 0];
    const rotation = config.transform?.rotation ?? [0, 0, 0];
    const scale = config.transform?.scale ?? [1, 1, 1];

    root.position.set(position[0], position[1], position[2]);
    root.rotation.set(rotation[0], rotation[1], rotation[2]);
    root.scale.set(scale[0], scale[1], scale[2]);

    // -----------------------------------------------------------------
    // Load GLB mesh (synchronous via cached loader)
    // -----------------------------------------------------------------
    const meshUrl = config.assets?.meshUrl;
    let glbRoot = null;

    if (meshUrl) {
        const glb = ctx.glbLoader(meshUrl);
        // glb may be the scene graph itself or have a .scene property
        glbRoot = glb.scene ? glb.scene : glb;
    }

    if (glbRoot) {
        root.add(glbRoot);
    }

    // -----------------------------------------------------------------
    // Apply cinematic primitives
    // -----------------------------------------------------------------
    if (Array.isArray(config.cinematicPrimitives)) {
        config.cinematicPrimitives.forEach((prim) => {
            const fn = ctx.primitives[prim.name];
            if (typeof fn === 'function') {
                fn(root, prim.params);
            }
        });
    }

    // -----------------------------------------------------------------
    // Interaction handlers
    // -----------------------------------------------------------------
    const originalY = root.position.y;
    const activeTimelines = [];

    root.userData.handlers = {};

    // Hover – rise‑in effect (0.15 scene units up on enter, revert on leave)
    root.userData.handlers.hoverEnter = () => {
        const tl = gsap.to(root.position, {
            y: originalY + 0.15,
            duration: 0.2,
            ease: 'power3.out',
        });
        activeTimelines.push(tl);
    };

    root.userData.handlers.hoverLeave = () => {
        const tl = gsap.to(root.position, {
            y: originalY,
            duration: 0.2,
            ease: 'power3.out',
        });
        activeTimelines.push(tl);
    };

    // Click – emit selection event
    root.userData.handlers.click = () => {
        if (typeof ctx.emit === 'function') {
            ctx.emit('hub-collection.select');
        }
    };

    // Store any data bindings for external systems (no runtime logic here)
    root.userData.dataBindings = config.dataBindings ?? [];

    // -----------------------------------------------------------------
    // Cleanup routine
    // -----------------------------------------------------------------
    root.userData.cleanup = () => {
        // Dispose geometries and materials inside the loaded GLB
        if (glbRoot) {
            glbRoot.traverse((node) => {
                if (node.isMesh) {
                    if (node.geometry) node.geometry.dispose();
                    if (node.material) {
                        if (Array.isArray(node.material)) {
                            node.material.forEach((m) => m.dispose());
                        } else {
                            node.material.dispose();
                        }
                    }
                }
            });
        }

        // Kill all GSAP timelines created for this node
        activeTimelines.forEach((tl) => tl.kill());
        activeTimelines.length = 0;

        // Detach from parent if still attached
        if (root.parent) {
            root.parent.remove(root);
        }
    };

    return root;
}
